using System.IO;
using System.Windows;
using System.Windows.Controls;
using PracticeManager.Core;
using PracticeManager.Persistence;
namespace PracticeManager.Desktop;
public partial class MainWindow : Window
{
 LocalPractice? service; bool setup;
 LocalPractice S=>service??throw new InvalidOperationException("Local store unavailable.");
 public MainWindow(){InitializeComponent();try{var folder=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"CRC Practice Manager DEV");service=new LocalPractice(Path.Combine(folder,"practice-dev.db"));ShowLogin();}catch(Exception e){LoginMessage.Text="Cannot open development database: "+e.Message;LoginButton.IsEnabled=false;}}
 void Run(Action a){try{a();}catch(UnauthorizedAccessException){Status.Text="Access denied. Sign in again if your session expired.";}catch(ArgumentException e){MessageBox.Show(this,e.Message,"Check entry",MessageBoxButton.OK,MessageBoxImage.Warning);}catch(Exception){MessageBox.Show(this,"Operation failed. No successful change is assumed.","Development application",MessageBoxButton.OK,MessageBoxImage.Error);}}
 void ShowLogin(){S.Logout();Workspace.Visibility=Visibility.Collapsed;SignOut.Visibility=Visibility.Collapsed;LoginPanel.Visibility=Visibility.Visible;setup=!S.IsInitialized();SetupPanel.Visibility=ConfirmPanel.Visibility=setup?Visibility.Visible:Visibility.Collapsed;LoginHeading.Text=setup?"Set up your practice":"Sign in";LoginButton.Content=setup?"Create company":"Sign in";Password.Clear();Confirm.Clear();LoginMessage.Text="";Username.Focus();}
 void Login_Click(object sender,RoutedEventArgs e){try{if(setup){if(Password.Password!=Confirm.Password)throw new ArgumentException("Passwords do not match.");S.Bootstrap(Firm.Text,Username.Text,Password.Password,Prefix.Text);setup=false;ShowLogin();LoginMessage.Text="Company created. Sign in with your new credentials.";return;}if(!S.Login(Username.Text,Password.Password)){LoginMessage.Text="Sign-in unsuccessful. Check credentials or try later.";return;}LoginPanel.Visibility=Visibility.Collapsed;Workspace.Visibility=Visibility.Visible;SignOut.Visibility=Visibility.Visible;FirmLabel.Text=S.FirmName();CrmNav.IsEnabled=S.Can("Clients.View");Dashboard();}catch(ArgumentException ex){LoginMessage.Text=ex.Message;}catch(Exception){LoginMessage.Text="Operation failed. Check the local development database.";}finally{Password.Clear();Confirm.Clear();}}
 void SignOut_Click(object sender,RoutedEventArgs e){ClientGrid.ItemsSource=null;ContactGrid.ItemsSource=null;ClientCount.Text="";ShowLogin();}
 void Dashboard(){DashboardPanel.Visibility=Visibility.Visible;CrmPanel.Visibility=Visibility.Collapsed;ClientCount.Text=S.Can("Clients.View")?S.SearchClients("").Count.ToString():"Restricted";Status.Text="Development preview · Local database · No live data";}
 void Dashboard_Click(object sender,RoutedEventArgs e)=>Run(Dashboard);
 void Crm_Click(object sender,RoutedEventArgs e)=>Run(()=>{DashboardPanel.Visibility=Visibility.Collapsed;CrmPanel.Visibility=Visibility.Visible;RefreshClients();});
 void Search_Changed(object sender,TextChangedEventArgs e){if(service!=null&&CrmPanel?.Visibility==Visibility.Visible)Run(()=>RefreshClients());}
 void RefreshClients(long? select=null){ClientGrid.ItemsSource=null;ContactGrid.ItemsSource=null;var rows=S.SearchClients(Search.Text);ClientGrid.ItemsSource=rows;if(select!=null)ClientGrid.SelectedItem=rows.FirstOrDefault(x=>x.Id==select);NewClientButton.IsEnabled=S.Can("Clients.Edit");UpdateContacts();}
 void Client_Changed(object sender,SelectionChangedEventArgs e){if(service!=null&&CrmPanel?.Visibility==Visibility.Visible)Run(UpdateContacts);}
 void Contact_Changed(object sender,SelectionChangedEventArgs e){if(service!=null&&CrmPanel?.Visibility==Visibility.Visible)Run(UpdateButtons);}
 void UpdateButtons(){var client=ClientGrid.SelectedItem as Client;EditClientButton.IsEnabled=client!=null&&S.Can("Clients.Edit");var edit=client?.Status=="Active"&&S.Can("Contacts.View")&&S.Can("Contacts.Edit");NewContactButton.IsEnabled=edit;EditContactButton.IsEnabled=edit&&ContactGrid.SelectedItem is Contact;}
 void UpdateContacts(){var client=ClientGrid.SelectedItem as Client;ContactGrid.ItemsSource=null;ContactsHeading.Text=client==null?"Select a client to view contacts":$"Contacts · {client.DisplayName}";if(client!=null&&S.Can("Contacts.View"))ContactGrid.ItemsSource=S.Contacts(client.Id);UpdateButtons();}
 void NewClient_Click(object sender,RoutedEventArgs e)=>Run(()=>EditClient(null));
 void EditClient_Click(object sender,RoutedEventArgs e)=>Run(()=>{if(ClientGrid.SelectedItem is Client x)EditClient(x);});
 void EditClient(Client? x){if(!S.Can("Clients.Edit"))throw new UnauthorizedAccessException();var fields=new (string,string)[]{("Client type",x?.Type??"Business / Company"),("Company",x?.Company??""),("First name",x?.First??""),("Last name",x?.Last??""),("Email",x?.Email??""),("Phone",x?.Phone??""),("Address 1",x?.Address1??""),("Address 2",x?.Address2??""),("City",x?.City??""),("State",x?.State??""),("ZIP",x?.Zip??""),("Notes",x?.Notes??""),("Status (Active / Inactive)",x?.Status??"Active")};long? savedId=null;if(EditDialog(x==null?"New client":"Edit client",fields,v=>{savedId=S.SaveClient(new Client(x?.Id??0,x?.Number??"",v[0],v[1],v[2],v[3],v[4],v[5],v[6],v[7],v[8],v[9],v[10],v[11],v[12]));})){Search.Text="";RefreshClients(savedId);}}
 void NewContact_Click(object sender,RoutedEventArgs e)=>Run(()=>EditContact(null));
 void EditContact_Click(object sender,RoutedEventArgs e)=>Run(()=>{if(ContactGrid.SelectedItem is Contact x)EditContact(x);});
 void EditContact(Contact? x){if(ClientGrid.SelectedItem is not Client client)return;if(!S.Can("Contacts.Edit"))throw new UnauthorizedAccessException();var fields=new (string,string)[]{("First name",x?.First??""),("Last name",x?.Last??""),("Title",x?.Title??""),("Email",x?.Email??""),("Phone",x?.Phone??""),("Primary (Yes / No)",x?.Primary==true?"Yes":"No")};if(EditDialog("Contact · "+client.DisplayName,fields,v=>{if(!string.Equals(v[5],"Yes",StringComparison.OrdinalIgnoreCase)&&!string.Equals(v[5],"No",StringComparison.OrdinalIgnoreCase))throw new ArgumentException("Enter Yes or No for Primary.");S.SaveContact(new Contact(x?.Id??0,client.Id,v[0],v[1],v[2],v[3],v[4],string.Equals(v[5],"Yes",StringComparison.OrdinalIgnoreCase)));}))UpdateContacts();}
 bool EditDialog(string title,(string Label,string Value)[] fields,Action<string[]> save){var dialog=new Window{Owner=this,Title=title,Width=480,Height=Math.Min(710,150+fields.Length*64),WindowStartupLocation=WindowStartupLocation.CenterOwner,ShowInTaskbar=false,Background=System.Windows.Media.Brushes.White};var panel=new DockPanel{Margin=new Thickness(20)};var footer=new StackPanel{Orientation=Orientation.Horizontal,HorizontalAlignment=HorizontalAlignment.Right};DockPanel.SetDock(footer,Dock.Bottom);var ok=new Button{Content="Save",IsDefault=true};var cancel=new Button{Content="Cancel",IsCancel=true};footer.Children.Add(ok);footer.Children.Add(cancel);panel.Children.Add(footer);var stack=new StackPanel();var getters=new List<Func<string>>();foreach(var (label,value) in fields){stack.Children.Add(new TextBlock{Text=label});string[]? choices=label=="Client type"?Validation.ClientTypes.ToArray():label.StartsWith("Status (")?new[]{"Active","Inactive"}:label.StartsWith("Primary (")?new[]{"Yes","No"}:null;if(choices!=null){var combo=new ComboBox{ItemsSource=choices,SelectedItem=value,Margin=new Thickness(0,3,0,8),Padding=new Thickness(7)};getters.Add(()=>combo.SelectedItem as string??"");stack.Children.Add(combo);}else{var box=new TextBox{Text=value};getters.Add(()=>box.Text);stack.Children.Add(box);}}panel.Children.Add(new ScrollViewer{Content=stack,VerticalScrollBarVisibility=ScrollBarVisibility.Auto});dialog.Content=panel;ok.Click+=(_,_)=>{try{save(getters.Select(g=>g()).ToArray());dialog.DialogResult=true;}catch(ArgumentException ex){MessageBox.Show(dialog,ex.Message,"Check entry");}catch(UnauthorizedAccessException){MessageBox.Show(dialog,"Permission denied.");}catch(Exception){MessageBox.Show(dialog,"Operation failed; refresh the register before retrying.");}};return dialog.ShowDialog()==true;}
}
